package algorithms.sorting;

import java.util.Arrays;

/**
 * Core Sorting Algorithms
 * QuickSort: O(n log n) avg, O(n²) worst
 * MergeSort: O(n log n) always, O(n) space
 * HeapSort:  O(n log n) always, O(1) space
 */
public class SortingAlgorithms {

    // ---- QuickSort ----
    public static void quickSort(int[] arr, int low, int high) {
        if (low < high) {
            int pivot = partition(arr, low, high);
            quickSort(arr, low, pivot - 1);
            quickSort(arr, pivot + 1, high);
        }
    }

    private static int partition(int[] arr, int low, int high) {
        int pivot = arr[high];
        int i = low - 1;
        for (int j = low; j < high; j++) {
            if (arr[j] <= pivot) {
                i++;
                int tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp;
            }
        }
        int tmp = arr[i+1]; arr[i+1] = arr[high]; arr[high] = tmp;
        return i + 1;
    }

    // ---- MergeSort ----
    public static void mergeSort(int[] arr, int left, int right) {
        if (left >= right) return;
        int mid = (left + right) / 2;
        mergeSort(arr, left, mid);
        mergeSort(arr, mid + 1, right);
        merge(arr, left, mid, right);
    }

    private static void merge(int[] arr, int left, int mid, int right) {
        int[] temp = Arrays.copyOfRange(arr, left, right + 1);
        int i = 0, j = mid - left + 1, k = left;
        while (i <= mid - left && j <= right - left) {
            if (temp[i] <= temp[j]) arr[k++] = temp[i++];
            else arr[k++] = temp[j++];
        }
        while (i <= mid - left) arr[k++] = temp[i++];
        while (j <= right - left) arr[k++] = temp[j++];
    }

    // ---- HeapSort ----
    public static void heapSort(int[] arr) {
        int n = arr.length;
        for (int i = n / 2 - 1; i >= 0; i--) heapify(arr, n, i);
        for (int i = n - 1; i > 0; i--) {
            int tmp = arr[0]; arr[0] = arr[i]; arr[i] = tmp;
            heapify(arr, i, 0);
        }
    }

    private static void heapify(int[] arr, int n, int i) {
        int largest = i, left = 2*i+1, right = 2*i+2;
        if (left < n && arr[left] > arr[largest]) largest = left;
        if (right < n && arr[right] > arr[largest]) largest = right;
        if (largest != i) {
            int tmp = arr[i]; arr[i] = arr[largest]; arr[largest] = tmp;
            heapify(arr, n, largest);
        }
    }

    // ---- Counting Sort (for integers in range [0, k]) ----
    public static int[] countingSort(int[] arr, int k) {
        int[] count = new int[k + 1];
        for (int x : arr) count[x]++;
        for (int i = 1; i <= k; i++) count[i] += count[i-1];
        int[] out = new int[arr.length];
        for (int i = arr.length - 1; i >= 0; i--)
            out[--count[arr[i]]] = arr[i];
        return out;
    }

    public static void main(String[] args) {
        int[] arr1 = {10,7,8,9,1,5};
        quickSort(arr1, 0, arr1.length - 1);
        System.out.println(Arrays.toString(arr1)); // [1,5,7,8,9,10]

        int[] arr2 = {38,27,43,3,9,82,10};
        mergeSort(arr2, 0, arr2.length - 1);
        System.out.println(Arrays.toString(arr2)); // [3,9,10,27,38,43,82]

        int[] arr3 = {12,11,13,5,6,7};
        heapSort(arr3);
        System.out.println(Arrays.toString(arr3)); // [5,6,7,11,12,13]
    }
}

package algorithms.searching;

/**
 * Binary Search Variants
 * All O(log n) — works on sorted arrays.
 */
public class BinarySearch {

    // 1. Standard binary search
    public static int search(int[] nums, int target) {
        int left = 0, right = nums.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2; // avoid overflow
            if (nums[mid] == target) return mid;
            if (nums[mid] < target) left = mid + 1;
            else right = mid - 1;
        }
        return -1;
    }

    // 2. Find leftmost (first occurrence)
    public static int searchLeft(int[] nums, int target) {
        int left = 0, right = nums.length - 1, result = -1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) { result = mid; right = mid - 1; }
            else if (nums[mid] < target) left = mid + 1;
            else right = mid - 1;
        }
        return result;
    }

    // 3. Find rightmost (last occurrence)
    public static int searchRight(int[] nums, int target) {
        int left = 0, right = nums.length - 1, result = -1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) { result = mid; left = mid + 1; }
            else if (nums[mid] < target) left = mid + 1;
            else right = mid - 1;
        }
        return result;
    }

    // 4. Search in rotated sorted array
    public static int searchRotated(int[] nums, int target) {
        int left = 0, right = nums.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) return mid;
            if (nums[left] <= nums[mid]) { // left half sorted
                if (target >= nums[left] && target < nums[mid]) right = mid - 1;
                else left = mid + 1;
            } else { // right half sorted
                if (target > nums[mid] && target <= nums[right]) left = mid + 1;
                else right = mid - 1;
            }
        }
        return -1;
    }

    // 5. Find minimum in rotated sorted array
    public static int findMin(int[] nums) {
        int left = 0, right = nums.length - 1;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] > nums[right]) left = mid + 1;
            else right = mid;
        }
        return nums[left];
    }

    // 6. First bad version
    public static int firstBadVersion(int n) {
        int left = 1, right = n;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (isBadVersion(mid)) right = mid;
            else left = mid + 1;
        }
        return left;
    }

    private static boolean isBadVersion(int v) { return v >= 4; } // mock

    // 7. Peak element
    public static int findPeakElement(int[] nums) {
        int left = 0, right = nums.length - 1;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] > nums[mid + 1]) right = mid;
            else left = mid + 1;
        }
        return left;
    }

    public static void main(String[] args) {
        int[] arr = {1, 3, 3, 5, 7, 9};
        System.out.println(search(arr, 3));      // 1 or 2
        System.out.println(searchLeft(arr, 3));  // 1
        System.out.println(searchRight(arr, 3)); // 2
        int[] rotated = {4,5,6,7,0,1,2};
        System.out.println(searchRotated(rotated, 0)); // 4
        System.out.println(findMin(rotated));           // 0
    }
}

package algorithms.graphs;

import java.util.*;

/**
 * Graph Traversal — BFS and DFS
 * BFS: shortest path in unweighted graph, level-order exploration
 * DFS: cycle detection, topological sort, connected components
 */
public class GraphTraversal {

    private final int V;
    private final List<List<Integer>> adj;

    public GraphTraversal(int v) {
        this.V = v;
        adj = new ArrayList<>();
        for (int i = 0; i < v; i++) adj.add(new ArrayList<>());
    }

    public void addEdge(int u, int v) { adj.get(u).add(v); }

    // ---- BFS ----
    public List<Integer> bfs(int source) {
        List<Integer> order = new ArrayList<>();
        boolean[] visited = new boolean[V];
        Queue<Integer> queue = new LinkedList<>();
        visited[source] = true;
        queue.offer(source);
        while (!queue.isEmpty()) {
            int node = queue.poll();
            order.add(node);
            for (int neighbor : adj.get(node)) {
                if (!visited[neighbor]) {
                    visited[neighbor] = true;
                    queue.offer(neighbor);
                }
            }
        }
        return order;
    }

    // ---- DFS (iterative) ----
    public List<Integer> dfsIterative(int source) {
        List<Integer> order = new ArrayList<>();
        boolean[] visited = new boolean[V];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(source);
        while (!stack.isEmpty()) {
            int node = stack.pop();
            if (visited[node]) continue;
            visited[node] = true;
            order.add(node);
            for (int neighbor : adj.get(node))
                if (!visited[neighbor]) stack.push(neighbor);
        }
        return order;
    }

    // ---- DFS (recursive) ----
    public void dfsRecursive(int node, boolean[] visited, List<Integer> order) {
        visited[node] = true;
        order.add(node);
        for (int neighbor : adj.get(node))
            if (!visited[neighbor]) dfsRecursive(neighbor, visited, order);
    }

    // ---- Detect Cycle (undirected) ----
    public boolean hasCycleUndirected() {
        boolean[] visited = new boolean[V];
        for (int i = 0; i < V; i++)
            if (!visited[i] && dfsCycle(i, -1, visited)) return true;
        return false;
    }

    private boolean dfsCycle(int node, int parent, boolean[] visited) {
        visited[node] = true;
        for (int neighbor : adj.get(node)) {
            if (!visited[neighbor]) {
                if (dfsCycle(neighbor, node, visited)) return true;
            } else if (neighbor != parent) return true;
        }
        return false;
    }

    // ---- Shortest Path (BFS, unweighted) ----
    public int[] shortestPath(int source) {
        int[] dist = new int[V];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[source] = 0;
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(source);
        while (!queue.isEmpty()) {
            int node = queue.poll();
            for (int neighbor : adj.get(node)) {
                if (dist[neighbor] == Integer.MAX_VALUE) {
                    dist[neighbor] = dist[node] + 1;
                    queue.offer(neighbor);
                }
            }
        }
        return dist;
    }

    // ---- Connected Components ----
    public int countComponents() {
        boolean[] visited = new boolean[V];
        int count = 0;
        for (int i = 0; i < V; i++) {
            if (!visited[i]) {
                dfsRecursive(i, visited, new ArrayList<>());
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        GraphTraversal g = new GraphTraversal(6);
        g.addEdge(0, 1); g.addEdge(0, 2);
        g.addEdge(1, 3); g.addEdge(2, 4);
        g.addEdge(3, 5);
        System.out.println("BFS: " + g.bfs(0));           // [0,1,2,3,4,5]
        System.out.println("DFS: " + g.dfsIterative(0));  // [0,2,4,1,3,5]
        System.out.println("Dist: " + Arrays.toString(g.shortestPath(0)));
    }
}

package algorithms.dynamic_programming;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

/**
 * Dynamic Programming — Core Patterns in Java
 * Memoization (top-down) vs Tabulation (bottom-up)
 */
public class DPFundamentals {

    // 1. Fibonacci — memoization
    private static Map<Integer, Long> memo = new HashMap<>();
    public static long fib(int n) {
        if (n <= 1) return n;
        if (memo.containsKey(n)) return memo.get(n);
        long result = fib(n-1) + fib(n-2);
        memo.put(n, result);
        return result;
    }

    // 2. Climbing Stairs
    public static int climbStairs(int n) {
        if (n <= 2) return n;
        int a = 1, b = 2;
        for (int i = 3; i <= n; i++) { int c = a + b; a = b; b = c; }
        return b;
    }

    // 3. House Robber
    public static int rob(int[] nums) {
        if (nums.length == 0) return 0;
        if (nums.length == 1) return nums[0];
        int prev2 = nums[0], prev1 = Math.max(nums[0], nums[1]);
        for (int i = 2; i < nums.length; i++) {
            int curr = Math.max(prev1, prev2 + nums[i]);
            prev2 = prev1; prev1 = curr;
        }
        return prev1;
    }

    // 4. Longest Common Subsequence
    public static int lcs(String s1, String s2) {
        int m = s1.length(), n = s2.length();
        int[][] dp = new int[m+1][n+1];
        for (int i = 1; i <= m; i++)
            for (int j = 1; j <= n; j++)
                dp[i][j] = s1.charAt(i-1) == s2.charAt(j-1)
                    ? dp[i-1][j-1] + 1
                    : Math.max(dp[i-1][j], dp[i][j-1]);
        return dp[m][n];
    }

    // 5. 0/1 Knapsack
    public static int knapsack(int[] weights, int[] values, int capacity) {
        int n = weights.length;
        int[] dp = new int[capacity + 1];
        for (int i = 0; i < n; i++)
            for (int w = capacity; w >= weights[i]; w--)
                dp[w] = Math.max(dp[w], dp[w - weights[i]] + values[i]);
        return dp[capacity];
    }

    // 6. Coin Change
    public static int coinChange(int[] coins, int amount) {
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, amount + 1);
        dp[0] = 0;
        for (int coin : coins)
            for (int a = coin; a <= amount; a++)
                dp[a] = Math.min(dp[a], dp[a - coin] + 1);
        return dp[amount] > amount ? -1 : dp[amount];
    }

    // 7. Unique Paths
    public static int uniquePaths(int m, int n) {
        int[] dp = new int[n];
        Arrays.fill(dp, 1);
        for (int i = 1; i < m; i++)
            for (int j = 1; j < n; j++)
                dp[j] += dp[j-1];
        return dp[n-1];
    }

    // 8. Word Break
    public static boolean wordBreak(String s, java.util.List<String> wordDict) {
        java.util.Set<String> dict = new java.util.HashSet<>(wordDict);
        boolean[] dp = new boolean[s.length() + 1];
        dp[0] = true;
        for (int i = 1; i <= s.length(); i++)
            for (int j = 0; j < i; j++)
                if (dp[j] && dict.contains(s.substring(j, i))) { dp[i] = true; break; }
        return dp[s.length()];
    }

    public static void main(String[] args) {
        System.out.println(fib(10));                          // 55
        System.out.println(climbStairs(5));                   // 8
        System.out.println(rob(new int[]{2,7,9,3,1}));       // 12
        System.out.println(lcs("ABCBDAB", "BDCAB"));         // 4
        System.out.println(coinChange(new int[]{1,5,11}, 15)); // 3
        System.out.println(uniquePaths(3, 7));                // 28
    }
}

package algorithms.searching;

import java.util.*;

/**
 * Two Pointer Patterns
 * Used for: sorted arrays, pairs, subarrays
 */
public class TwoPointers {

    // 1. Two Sum in sorted array
    public static int[] twoSum(int[] nums, int target) {
        int left = 0, right = nums.length - 1;
        while (left < right) {
            int sum = nums[left] + nums[right];
            if (sum == target) return new int[]{left, right};
            if (sum < target) left++;
            else right--;
        }
        return new int[]{-1, -1};
    }

    // 2. 3Sum
    public static List<List<Integer>> threeSum(int[] nums) {
        Arrays.sort(nums);
        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < nums.length - 2; i++) {
            if (i > 0 && nums[i] == nums[i-1]) continue;
            int left = i+1, right = nums.length-1;
            while (left < right) {
                int sum = nums[i] + nums[left] + nums[right];
                if (sum == 0) {
                    result.add(Arrays.asList(nums[i], nums[left], nums[right]));
                    while (left < right && nums[left] == nums[left+1]) left++;
                    while (left < right && nums[right] == nums[right-1]) right--;
                    left++; right--;
                } else if (sum < 0) left++;
                else right--;
            }
        }
        return result;
    }

    // 3. Container with Most Water
    public static int maxArea(int[] height) {
        int left = 0, right = height.length - 1, max = 0;
        while (left < right) {
            max = Math.max(max, Math.min(height[left], height[right]) * (right - left));
            if (height[left] < height[right]) left++;
            else right--;
        }
        return max;
    }

    // 4. Trapping Rain Water
    public static int trap(int[] height) {
        int left = 0, right = height.length - 1;
        int maxLeft = 0, maxRight = 0, water = 0;
        while (left < right) {
            if (height[left] <= height[right]) {
                if (height[left] >= maxLeft) maxLeft = height[left];
                else water += maxLeft - height[left];
                left++;
            } else {
                if (height[right] >= maxRight) maxRight = height[right];
                else water += maxRight - height[right];
                right--;
            }
        }
        return water;
    }

    // 5. Remove Duplicates from Sorted Array
    public static int removeDuplicates(int[] nums) {
        if (nums.length == 0) return 0;
        int slow = 0;
        for (int fast = 1; fast < nums.length; fast++)
            if (nums[fast] != nums[slow]) nums[++slow] = nums[fast];
        return slow + 1;
    }

    // 6. Sort Colors (Dutch National Flag)
    public static void sortColors(int[] nums) {
        int low = 0, mid = 0, high = nums.length - 1;
        while (mid <= high) {
            if (nums[mid] == 0) {
                int tmp = nums[low]; nums[low] = nums[mid]; nums[mid] = tmp;
                low++; mid++;
            } else if (nums[mid] == 1) {
                mid++;
            } else {
                int tmp = nums[mid]; nums[mid] = nums[high]; nums[high] = tmp;
                high--;
            }
        }
    }

    public static void main(String[] args) {
        System.out.println(Arrays.toString(twoSum(new int[]{2,7,11,15}, 9))); // [0,1]
        System.out.println(threeSum(new int[]{-1,0,1,2,-1,-4}));
        System.out.println(maxArea(new int[]{1,8,6,2,5,4,8,3,7})); // 49
        System.out.println(trap(new int[]{0,1,0,2,1,0,1,3,2,1,2,1})); // 6
    }
}

package algorithms.searching;

import java.util.*;

/**
 * Sliding Window Patterns — Fixed and Variable Size
 * O(n) solutions for subarray/substring problems.
 */
public class SlidingWindow {

    // 1. Max sum subarray of size k
    public static int maxSumSubarray(int[] arr, int k) {
        int windowSum = 0, maxSum = 0;
        for (int i = 0; i < k; i++) windowSum += arr[i];
        maxSum = windowSum;
        for (int i = k; i < arr.length; i++) {
            windowSum += arr[i] - arr[i - k];
            maxSum = Math.max(maxSum, windowSum);
        }
        return maxSum;
    }

    // 2. Longest substring without repeating chars
    public static int lengthOfLongestSubstring(String s) {
        Map<Character, Integer> charIndex = new HashMap<>();
        int maxLen = 0, left = 0;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            if (charIndex.containsKey(c) && charIndex.get(c) >= left)
                left = charIndex.get(c) + 1;
            charIndex.put(c, right);
            maxLen = Math.max(maxLen, right - left + 1);
        }
        return maxLen;
    }

    // 3. Minimum window substring
    public static String minWindow(String s, String t) {
        Map<Character, Integer> need = new HashMap<>();
        for (char c : t.toCharArray()) need.merge(c, 1, Integer::sum);
        int missing = t.length(), left = 0, start = 0, minLen = Integer.MAX_VALUE;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            if (need.getOrDefault(c, 0) > 0) missing--;
            need.merge(c, -1, Integer::sum);
            if (missing == 0) {
                while (need.getOrDefault(s.charAt(left), 0) < 0)
                    need.merge(s.charAt(left++), 1, Integer::sum);
                if (right - left + 1 < minLen) { minLen = right - left + 1; start = left; }
                need.merge(s.charAt(left++), 1, Integer::sum);
                missing++;
            }
        }
        return minLen == Integer.MAX_VALUE ? "" : s.substring(start, start + minLen);
    }

    // 4. Longest repeating character replacement
    public static int characterReplacement(String s, int k) {
        int[] freq = new int[26];
        int left = 0, maxFreq = 0, maxLen = 0;
        for (int right = 0; right < s.length(); right++) {
            freq[s.charAt(right) - 'A']++;
            maxFreq = Math.max(maxFreq, freq[s.charAt(right) - 'A']);
            if ((right - left + 1) - maxFreq > k)
                freq[s.charAt(left++) - 'A']--;
            maxLen = Math.max(maxLen, right - left + 1);
        }
        return maxLen;
    }

    // 5. Find all anagrams in string
    public static List<Integer> findAnagrams(String s, String p) {
        List<Integer> result = new ArrayList<>();
        int[] pCount = new int[26], wCount = new int[26];
        for (char c : p.toCharArray()) pCount[c - 'a']++;
        for (int i = 0; i < s.length(); i++) {
            wCount[s.charAt(i) - 'a']++;
            if (i >= p.length()) wCount[s.charAt(i - p.length()) - 'a']--;
            if (Arrays.equals(pCount, wCount)) result.add(i - p.length() + 1);
        }
        return result;
    }

    public static void main(String[] args) {
        System.out.println(maxSumSubarray(new int[]{2,1,5,1,3,2}, 3));  // 9
        System.out.println(lengthOfLongestSubstring("abcabcbb"));         // 3
        System.out.println(minWindow("ADOBECODEBANC", "ABC"));            // BANC
        System.out.println(characterReplacement("AABABBA", 1));           // 4
        System.out.println(findAnagrams("cbaebabacd", "abc"));            // [0, 6]
    }
}

package algorithms.searching;

import java.util.*;

/**
 * Stack & Queue Patterns
 */
public class StackQueuePatterns {

    // 1. Valid Parentheses
    public static boolean isValid(String s) {
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            if (c == '(' || c == '[' || c == '{') stack.push(c);
            else {
                if (stack.isEmpty()) return false;
                char top = stack.pop();
                if (c==')' && top!='(') return false;
                if (c==']' && top!='[') return false;
                if (c=='}' && top!='{') return false;
            }
        }
        return stack.isEmpty();
    }

    // 2. Daily Temperatures (Monotonic Stack)
    public static int[] dailyTemperatures(int[] temps) {
        int n = temps.length;
        int[] result = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && temps[i] > temps[stack.peek()])
                result[stack.peek()] = i - stack.pop();
            stack.push(i);
        }
        return result;
    }

    // 3. Largest Rectangle in Histogram
    public static int largestRectangle(int[] heights) {
        Deque<Integer> stack = new ArrayDeque<>();
        int max = 0;
        int[] h = Arrays.copyOf(heights, heights.length + 1); // sentinel
        for (int i = 0; i <= h.length - 1; i++) {
            while (!stack.isEmpty() && h[i] < h[stack.peek()]) {
                int height = h[stack.pop()];
                int width = stack.isEmpty() ? i : i - stack.peek() - 1;
                max = Math.max(max, height * width);
            }
            stack.push(i);
        }
        return max;
    }

    // 4. Min Stack
    static class MinStack {
        private Deque<Integer> stack = new ArrayDeque<>();
        private Deque<Integer> minStack = new ArrayDeque<>();
        public void push(int val) {
            stack.push(val);
            minStack.push(minStack.isEmpty() ? val : Math.min(val, minStack.peek()));
        }
        public void pop() { stack.pop(); minStack.pop(); }
        public int top() { return stack.peek(); }
        public int getMin() { return minStack.peek(); }
    }

    // 5. Evaluate RPN
    public static int evalRPN(String[] tokens) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (String t : tokens) {
            switch (t) {
                case "+" -> stack.push(stack.pop() + stack.pop());
                case "*" -> stack.push(stack.pop() * stack.pop());
                case "-" -> { int b = stack.pop(); stack.push(stack.pop() - b); }
                case "/" -> { int b = stack.pop(); stack.push(stack.pop() / b); }
                default  -> stack.push(Integer.parseInt(t));
            }
        }
        return stack.peek();
    }

    public static void main(String[] args) {
        System.out.println(isValid("({[]})"));              // true
        System.out.println(Arrays.toString(dailyTemperatures(new int[]{73,74,75,71,69,72,76,73})));
        System.out.println(largestRectangle(new int[]{2,1,5,6,2,3})); // 10
        System.out.println(evalRPN(new String[]{"2","1","+","3","*"})); // 9
    }
}

package algorithms.searching;

import java.util.*;

/**
 * HashMap / HashSet Patterns
 */
public class HashMapPatterns {

    // 1. Two Sum (unsorted)
    public static int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            int complement = target - nums[i];
            if (map.containsKey(complement)) return new int[]{map.get(complement), i};
            map.put(nums[i], i);
        }
        return new int[]{-1, -1};
    }

    // 2. Group Anagrams
    public static List<List<String>> groupAnagrams(String[] strs) {
        Map<String, List<String>> map = new HashMap<>();
        for (String s : strs) {
            char[] chars = s.toCharArray(); Arrays.sort(chars);
            String key = new String(chars);
            map.computeIfAbsent(key, k -> new ArrayList<>()).add(s);
        }
        return new ArrayList<>(map.values());
    }

    // 3. Top K frequent elements
    public static int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int n : nums) freq.merge(n, 1, Integer::sum);
        PriorityQueue<Integer> heap = new PriorityQueue<>(Comparator.comparingInt(freq::get));
        for (int key : freq.keySet()) {
            heap.offer(key);
            if (heap.size() > k) heap.poll();
        }
        int[] result = new int[k];
        for (int i = k-1; i >= 0; i--) result[i] = heap.poll();
        return result;
    }

    // 4. Subarray sum equals K
    public static int subarraySum(int[] nums, int k) {
        Map<Integer, Integer> prefixCount = new HashMap<>();
        prefixCount.put(0, 1);
        int count = 0, sum = 0;
        for (int num : nums) {
            sum += num;
            count += prefixCount.getOrDefault(sum - k, 0);
            prefixCount.merge(sum, 1, Integer::sum);
        }
        return count;
    }

    // 5. Longest consecutive sequence
    public static int longestConsecutive(int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int n : nums) set.add(n);
        int maxLen = 0;
        for (int n : set) {
            if (!set.contains(n - 1)) { // start of sequence
                int curr = n, len = 1;
                while (set.contains(curr + 1)) { curr++; len++; }
                maxLen = Math.max(maxLen, len);
            }
        }
        return maxLen;
    }

    public static void main(String[] args) {
        System.out.println(Arrays.toString(twoSum(new int[]{2,7,11,15}, 9))); // [0,1]
        System.out.println(groupAnagrams(new String[]{"eat","tea","tan","ate","nat","bat"}));
        System.out.println(Arrays.toString(topKFrequent(new int[]{1,1,1,2,2,3}, 2))); // [1,2]
        System.out.println(subarraySum(new int[]{1,1,1}, 2));  // 2
        System.out.println(longestConsecutive(new int[]{100,4,200,1,3,2})); // 4
    }
}

package algorithms.searching;

import java.util.*;

/**
 * Prefix Sum and Difference Array Patterns
 */
public class PrefixSum {

    // 1. Range sum query
    static class NumArray {
        private int[] prefix;
        public NumArray(int[] nums) {
            prefix = new int[nums.length + 1];
            for (int i = 0; i < nums.length; i++)
                prefix[i+1] = prefix[i] + nums[i];
        }
        public int sumRange(int l, int r) { return prefix[r+1] - prefix[l]; }
    }

    // 2. Subarray sum equals K (using prefix sum)
    public static int subarraySum(int[] nums, int k) {
        Map<Integer, Integer> count = new HashMap<>();
        count.put(0, 1);
        int sum = 0, result = 0;
        for (int num : nums) {
            sum += num;
            result += count.getOrDefault(sum - k, 0);
            count.merge(sum, 1, Integer::sum);
        }
        return result;
    }

    // 3. Product of Array Except Self
    public static int[] productExceptSelf(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];
        result[0] = 1;
        for (int i = 1; i < n; i++) result[i] = result[i-1] * nums[i-1];
        int right = 1;
        for (int i = n-1; i >= 0; i--) { result[i] *= right; right *= nums[i]; }
        return result;
    }

    // 4. Difference array (range update, point query)
    static class DifferenceArray {
        private int[] diff;
        public DifferenceArray(int n) { diff = new int[n + 1]; }
        // Add val to range [l, r]
        public void update(int l, int r, int val) { diff[l] += val; diff[r+1] -= val; }
        // Get final array after all updates
        public int[] result() {
            int[] res = new int[diff.length - 1];
            res[0] = diff[0];
            for (int i = 1; i < res.length; i++) res[i] = res[i-1] + diff[i];
            return res;
        }
    }

    // 5. Number of subarrays with bounded maximum
    public static int numSubarrayBoundedMax(int[] nums, int left, int right) {
        int result = 0, prev = -1, count = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] > right) { prev = i; count = 0; }
            else if (nums[i] >= left) { count = i - prev; }
            result += count;
        }
        return result;
    }

    public static void main(String[] args) {
        NumArray na = new NumArray(new int[]{-2,0,3,-5,2,-1});
        System.out.println(na.sumRange(0,2));  // 1
        System.out.println(na.sumRange(2,5));  // -1
        System.out.println(Arrays.toString(productExceptSelf(new int[]{1,2,3,4}))); // [24,12,8,6]
        System.out.println(subarraySum(new int[]{1,1,1}, 2)); // 2
    }
}

package algorithms.trees;

import java.util.*;

/**
 * Heap / PriorityQueue Patterns
 */
public class HeapPatterns {

    // 1. Kth largest element
    public static int findKthLargest(int[] nums, int k) {
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        for (int num : nums) {
            minHeap.offer(num);
            if (minHeap.size() > k) minHeap.poll();
        }
        return minHeap.peek();
    }

    // 2. K closest points to origin
    public static int[][] kClosest(int[][] points, int k) {
        PriorityQueue<int[]> maxHeap = new PriorityQueue<>(
            (a, b) -> (b[0]*b[0]+b[1]*b[1]) - (a[0]*a[0]+a[1]*a[1]));
        for (int[] p : points) {
            maxHeap.offer(p);
            if (maxHeap.size() > k) maxHeap.poll();
        }
        return maxHeap.toArray(new int[0][]);
    }

    // 3. Merge K sorted lists
    public static int[] mergeKSortedArrays(int[][] arrays) {
        PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        int totalLen = 0;
        for (int i = 0; i < arrays.length; i++) {
            if (arrays[i].length > 0) { heap.offer(new int[]{arrays[i][0], i, 0}); totalLen += arrays[i].length; }
        }
        int[] result = new int[totalLen];
        int idx = 0;
        while (!heap.isEmpty()) {
            int[] curr = heap.poll();
            result[idx++] = curr[0];
            int arrIdx = curr[1], elemIdx = curr[2];
            if (elemIdx + 1 < arrays[arrIdx].length)
                heap.offer(new int[]{arrays[arrIdx][elemIdx+1], arrIdx, elemIdx+1});
        }
        return result;
    }

    // 4. Find median from data stream
    static class MedianFinder {
        private PriorityQueue<Integer> lo = new PriorityQueue<>(Collections.reverseOrder()); // max heap
        private PriorityQueue<Integer> hi = new PriorityQueue<>(); // min heap

        public void addNum(int num) {
            lo.offer(num);
            hi.offer(lo.poll());
            if (lo.size() < hi.size()) lo.offer(hi.poll());
        }

        public double findMedian() {
            return lo.size() > hi.size() ? lo.peek() : (lo.peek() + hi.peek()) / 2.0;
        }
    }

    // 5. Task Scheduler
    public static int leastInterval(char[] tasks, int n) {
        int[] freq = new int[26];
        for (char t : tasks) freq[t - 'A']++;
        Arrays.sort(freq);
        int maxCount = freq[25];
        int idleSlots = (maxCount - 1) * n;
        for (int i = 24; i >= 0; i--) idleSlots -= Math.min(freq[i], maxCount - 1);
        return tasks.length + Math.max(0, idleSlots);
    }

    public static void main(String[] args) {
        System.out.println(findKthLargest(new int[]{3,2,1,5,6,4}, 2));  // 5
        System.out.println(Arrays.deepToString(kClosest(new int[][]{{1,3},{-2,2}}, 1))); // [[-2,2]]
        System.out.println(Arrays.toString(mergeKSortedArrays(new int[][]{{1,4,7},{2,5,8},{3,6,9}})));
        MedianFinder mf = new MedianFinder();
        mf.addNum(1); mf.addNum(2); System.out.println(mf.findMedian()); // 1.5
        mf.addNum(3); System.out.println(mf.findMedian()); // 2.0
    }
}
